mapper.select:
SELECT rr.id, rr.title, COALESCE(ui.nickname, ui.phone) AS user_name, ui.phone AS user_phone, ri.room_number, ai.name AS apartment_name, rr.priority, rr.status, rr.appointment_time, rr.create_time, su.name AS handler_name, prog.latest_progress FROM repair_request rr LEFT JOIN user_info ui ON rr.user_id = ui.id AND ui.is_deleted = 0 LEFT JOIN room_info ri ON rr.room_id = ri.id AND ri.is_deleted = 0 LEFT JOIN apartment_info ai ON ri.apartment_id = ai.id AND ai.is_deleted = 0 LEFT JOIN system_user su ON rr.handler_id = su.id AND su.is_deleted = 0 LEFT JOIN ( SELECT rp.request_id, rp.content AS latest_progress FROM repair_progress rp INNER JOIN ( SELECT request_id, MAX(create_time) AS max_time FROM repair_progress WHERE is_deleted = 0 GROUP BY request_id ) latest ON latest.request_id = rp.request_id AND latest.max_time = rp.create_time WHERE rp.is_deleted = 0 ) prog ON prog.request_id = rr.id
rr.is_deleted = 0
AND rr.title LIKE CONCAT('%', #{queryVo.title}, '%')
AND ui.phone LIKE CONCAT('%', #{queryVo.userPhone}, '%')
AND ai.name LIKE CONCAT('%', #{queryVo.apartmentName}, '%')
AND rr.status = #{queryVo.status}
AND rr.priority = #{queryVo.priority}
AND rr.handler_id = #{queryVo.handlerId}
AND rr.create_time >= #{queryVo.createTimeBegin}
AND rr.create_time <= #{queryVo.createTimeEnd}
ORDER BY rr.create_time DESC
